from blocks import *

def nc(text, sub, path='domains/'):
    import urllib.parse
    u = urllib.parse.quote('https://www.namecheap.com/' + path, safe='')
    return f'<a href="https://namecheap.pxf.io/c/8231073/1632743/5618?subId1={sub}&u={u}" target="_blank" rel="sponsored nofollow noopener">{text}</a>'

